    // msAbs = 1500
    // n = 1000
    // msAbs >= n * 1.5 -> 1500 >= 1500 -> true
    // So plural -> "2 seconds"

    // So the test is asserting that ms(1500, { long: true }) === "1 second"
    // But that's wrong — it should be "2 seconds"

    // The test is incorrect

