    // Math.round(0.999) = 1
    // msAbs = 999
    // n * 1.5 = 1500
    // 999 >= 1500? No
    // 999 > 1500? No
    // So both give singular: "1 second"

    // What about 1499ms?
    // 1499ms -> 1.499s
    // Math.round(1.499) = 1
    // msAbs = 1499
    // n * 1.5 = 1500
    // 1499 >= 1500? No
    // 1499 > 1500? No
    // Still singular

    // The only way the behavior changes is when the rounded value is 2 or more
    // and the threshold is exactly 1.5 times the unit
    // For example: 1500ms -> 2 seconds
